const LOGO_L='data:image/png;base64,',LOGO_R='data:image/png;base64,';
/* ===== STATE ===== */
const S={year:'2026-27',logo:'',role:'',emoji:'💻',manual:false,pkgOn:false,pkg:'',tag:'auto',bt:'PLACEMENT BATCH',sel:'FOR GETTING SELECTED AT',pre:'auto',sty:{},z:{},op:{},open:{},cp:null,icOpen:false,cmpOpen:false,lyOpen:true,pal:[],xf:{},tx:{},sk:null,deco:[],col:{},hid:{},nid:0,icon:'monitor',iconManual:false,sugg:[],key:'',hl:'both',act:null,lw:600,lh:400,logoSrc:'',st:[{name:'',course:COURSES[0],photo:'',upg:false}]};
const $=id=>document.getElementById(id),P=$('poster');
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function fileURL(f,cb){const r=new FileReader();r.onload=()=>cb(r.result);r.readAsDataURL(f)}
