let CI=null,CS={x:0,y:0,w:1,h:1},CB=1,dr=null;
const cs=()=>CB*$('cz').value/100;
function openCrop(src){const im=new Image();im.onload=()=>{CI=im;CS={x:0,y:0,w:im.width,h:im.height};CB=Math.min(700/im.width,400/im.height,2);$('cz').value=100;drawC();$('crm').style.display='flex'};im.src=src}
function drawC(){const k=cs(),c=$('cc'),x=c.getContext('2d');c.width=Math.round(CI.width*k);c.height=Math.round(CI.height*k);x.drawImage(CI,0,0,c.width,c.height);
 const r=[CS.x*k,CS.y*k,CS.w*k,CS.h*k];x.fillStyle='rgba(0,0,0,.55)';x.fillRect(0,0,c.width,r[1]);x.fillRect(0,r[1]+r[3],c.width,c.height);x.fillRect(0,r[1],r[0],r[3]);x.fillRect(r[0]+r[2],r[1],c.width,r[3]);x.strokeStyle='#e91e63';x.lineWidth=2;x.strokeRect(...r)}
const cc=$('cc'),pt=e=>{const b=cc.getBoundingClientRect(),k=cs();return{x:Math.max(0,Math.min(CI.width,(e.clientX-b.left)/k)),y:Math.max(0,Math.min(CI.height,(e.clientY-b.top)/k))}};
cc.onpointerdown=e=>{dr=pt(e);cc.setPointerCapture(e.pointerId)};
cc.onpointermove=e=>{if(!dr)return;const p=pt(e);CS={x:Math.min(dr.x,p.x),y:Math.min(dr.y,p.y),w:Math.abs(p.x-dr.x),h:Math.abs(p.y-dr.y)};drawC()};
cc.onpointerup=()=>{dr=null;if(CS.w<8||CS.h<8)cropAll()};
function cropAll(){CS={x:0,y:0,w:CI.width,h:CI.height};drawC()}
function autoTrim(){const c=document.createElement('canvas');c.width=CI.width;c.height=CI.height;const x=c.getContext('2d');x.drawImage(CI,0,0);const d=x.getImageData(0,0,c.width,c.height).data;let x0=c.width,y0=c.height,x1=0,y1=0;
 for(let y=0;y<c.height;y++)for(let i=0;i<c.width;i++){const j=(y*c.width+i)*4;if(d[j+3]>10&&Math.min(d[j],d[j+1],d[j+2])<235){if(i<x0)x0=i;if(i>x1)x1=i;if(y<y0)y0=y;if(y>y1)y1=y}}
 if(x1>x0&&y1>y0){const m=4;x0=Math.max(0,x0-m);y0=Math.max(0,y0-m);CS={x:x0,y:y0,w:Math.min(c.width,x1+m)-x0,h:Math.min(c.height,y1+m)-y0};drawC()}}
function cropOK(){const c=document.createElement('canvas');c.width=Math.round(CS.w);c.height=Math.round(CS.h);const x=c.getContext('2d');x.drawImage(CI,CS.x,CS.y,CS.w,CS.h,0,0,c.width,c.height);S.logo=c.toDataURL('image/png');S.lw=c.width;S.lh=c.height;S.logoSrc=CI.src;cropX();render()}
