function decoHTML(){return S.deco.map(d=>`<div data-k="x${d.id}" class="dc ${d.back?'bk':''}" style="left:${d.x}px;top:${d.y}px;width:${d.w}px;height:${d.h}px;color:${S.col['x'+d.id]||'#d8aa5a'}">${dsvg(d.t)}</div>`).join('')}
function drwUI(){const th=t=>`<button class="th" title="${DECO[t][1]}" style="color:${DECO[t][4]}" onclick="addDeco('${t}')">${dsvg(t)}</button>`;
 const sg=['divAS','sparkOr','dotsOr','rays3','blobHill',S.st.some(s=>s.upg)?'up':'seal'];
 $('drw').innerHTML=`<div class="cat">Suggested components</div><div class="ig">${sg.map(th).join('')}</div><details ${S.cmpOpen?'open':''} ontoggle="S.cmpOpen=this.open"><summary style="font-size:12px;cursor:pointer;margin:4px 0">All components ▾</summary>`+['Poster Style','Stars','Sparkles','Shapes','Ribbons','Badges'].map(c=>`<div class="cat">${c}</div><div class="ig">${Object.keys(DECO).filter(t=>DECO[t][0]===c).map(th).join('')}</div>`).join('')+`</details>`}
function addDeco(t){const a=DECO[t],id=++S.nid;S.deco.push({id,t,x:Math.round((1587-a[2])/2),y:Math.round((2245-a[3])/2),w:a[2],h:a[3],back:!!a[7]});S.col['x'+id]=a[4];S.sk='x'+id;render();openDeco(S.sk)}
const isDeco=k=>/^x\d+$/.test(k)||['sp1','sp2','dotL','dotR'].includes(k);
function openDeco(k){const b=$('tb'),x=/^x\d+$/.test(k);S.act=null;b.innerHTML=`<b>Element</b><input type="color" value="${S.col[k]||'#d8aa5a'}" oninput="setCol('${k}',this.value)" onchange="addPal(this.value)">${x?'<button class="s" onclick="dupDeco()">Duplicate</button><button class="s" onclick="backDeco()">Front / Back</button>':''}<button class="s" onclick="delDeco()">Delete</button>${palRow()}`;b.style.display='flex'}
function setCol(k,v){S.col[k]=v;applyXf()}
function delDeco(){const k=S.sk;if(!k)return;if(/^x\d+$/.test(k)){S.deco=S.deco.filter(d=>'x'+d.id!==k);delete S.xf[k];delete S.col[k]}else S.hid[k]=true;S.sk=null;hideTB();render()}
function dupDeco(){const k=S.sk,d=S.deco.find(d=>'x'+d.id===k);if(!d)return;const id=++S.nid;S.deco.push({...d,id,x:d.x+40,y:d.y+40});S.col['x'+id]=S.col[k];if(S.xf[k])S.xf['x'+id]={...S.xf[k]};S.sk='x'+id;render();openDeco(S.sk)}
function backDeco(){const d=S.deco.find(d=>'x'+d.id===S.sk);if(d){d.back=!d.back;render()}}
