const palHTML=()=>`<span style="font-size:11px;color:#666">Recent colors:</span>`+S.pal.map(c=>`<button class="sw" title="${c}" style="background:${c}" onclick="usePal('${c}')"></button>`).join('');
const palRow=()=>`<span class="palrow" style="display:inline-flex;align-items:center;gap:2px;margin-left:8px">${palHTML()}</span>`;
function addPal(c){S.pal=[c,...S.pal.filter(x=>x.toLowerCase()!==c.toLowerCase())].slice(0,14);try{localStorage.setItem('iipsPal',JSON.stringify(S.pal))}catch(e){}
 $('palr').innerHTML=palHTML();if(S.act)openTB(S.act);else if(S.sk&&isDeco(S.sk))openDeco(S.sk);tyUI()}
function usePal(c){if(S.act)tsty(S.act,'c',c);else if(S.sk&&isDeco(S.sk))setCol(S.sk,c);else return;addPal(c)}
