/* ===== ACTION BAR: layering / align / duplicate ===== */
function layer(d){const k=S.sk,e=k&&el(k);if(!e)return;const cur=S.z[k]!==undefined?S.z[k]:(parseInt(getComputedStyle(e).zIndex)||0);S.z[k]=cur+d;applyXf();commitSoon()}
function centerAx(a){const k=S.sk,e=k&&el(k);if(!e)return;const b=box(e),x=xfS(k);if(a==='x')x.x+=793.5-b.cx;else x.y+=1122.5-b.cy;e.style.transform=tr(x);updateOv();commitSoon()}
function dupAny(){if(/^x\d+$/.test(S.sk||''))dupDeco();else alert('Duplicate sirf Add Component se jode gaye elements ke liye hai.')}
