/* ===== UNDO / REDO (snapshot history) ===== */
const cl=o=>JSON.parse(JSON.stringify(o)),H={a:[],i:-1,last:''};let hT=null;
const pick=()=>({xf:cl(S.xf),tx:cl(S.tx),deco:cl(S.deco),col:cl(S.col),hid:cl(S.hid),z:cl(S.z),op:cl(S.op),sty:cl(S.sty),nid:S.nid,role:S.role,icon:S.icon,iconManual:S.iconManual,pkgOn:S.pkgOn,pkg:S.pkg,sel:S.sel,bt:S.bt,pre:S.pre,tag:S.tag,year:S.year,hl:S.hl,logo:S.logo,lw:S.lw,lh:S.lh,logoSrc:S.logoSrc,st:S.st.map(s=>({...s}))});
const hkey=p=>JSON.stringify({...p,logo:(p.logo||'').length,logoSrc:0,st:p.st.map(s=>({...s,photo:(s.photo||'').length+(s.photo||'').slice(-12)}))});
function commit(){const p=pick(),k=hkey(p);if(k===H.last)return;H.a=H.a.slice(0,H.i+1);H.a.push(p);if(H.a.length>60)H.a.shift();H.i=H.a.length-1;H.last=k;hist()}
function commitSoon(){clearTimeout(hT);hT=setTimeout(commit,350)}
function hist(){$('bu').disabled=H.i<=0;$('br').disabled=H.i>=H.a.length-1}
function restore(p){const q=cl({xf:p.xf,tx:p.tx,deco:p.deco,col:p.col,hid:p.hid,z:p.z,op:p.op,sty:p.sty});Object.assign(S,q,{nid:p.nid,role:p.role,icon:p.icon,iconManual:p.iconManual,pkgOn:p.pkgOn,pkg:p.pkg,sel:p.sel,bt:p.bt,pre:p.pre,tag:p.tag,year:p.year,hl:p.hl,logo:p.logo,lw:p.lw,lh:p.lh,logoSrc:p.logoSrc,st:p.st.map(s=>({...s})),sk:null,act:null,sugg:rank(p.role)});
 H.last=hkey(p);$('tb').style.display='none';syncUI();render();hist()}
function undo(){clearTimeout(hT);commit();if(H.i>0){H.i--;restore(H.a[H.i])}}
function redo(){if(H.i<H.a.length-1){H.i++;restore(H.a[H.i])}}
function syncUI(){$('role').value=S.role;$('sel').value=S.sel;$('bt').value=S.bt;$('pre').value=S.pre;$('tag').value=S.tag;$('year').value=YEARS.includes(S.year)?S.year:'Custom';$('showPkg').checked=S.pkgOn;$('pkg').value=S.pkg;$('pkg').style.display=S.pkgOn?'block':'none';$('hl').value=S.hl;stuUI();tyUI();icUI();drwUI();$('palr').innerHTML=palHTML()}
document.addEventListener('keydown',ev=>{if(!(ev.ctrlKey||ev.metaKey))return;const t=ev.target,k=ev.key.toLowerCase();if(/INPUT|TEXTAREA|SELECT/.test(t.tagName)||t.isContentEditable)return;
 if(k==='z'&&!ev.shiftKey){ev.preventDefault();undo()}else if(k==='y'||(k==='z'&&ev.shiftKey)){ev.preventDefault();redo()}});
setTimeout(()=>{commit()},700);
