$('mc').innerHTML=COURSES.map(c=>`<option>${c}</option>`).join('');
function openCM(){$('cm').style.display='flex'}
function cmTab(x){$('pm').style.display=x==='m'?'block':'none';$('ps').style.display=x==='s'?'block':'none';$('tm').className=x==='m'?'':'s';$('ts').className=x==='s'?'':'s'}
const pkgNum=s=>{const m=String(s||'').replace(/,/g,'').match(/\d+(\.\d+)?/);return m?m[0]:''};
const normCourse=s=>{s=(s||'').toLowerCase();if(!s.trim())return COURSES[0];if(/tech/.test(s)&&/\bit\b|\(it\)|information/.test(s))return COURSES[2];if(/tech/.test(s))return COURSES[1];if(/mca/.test(s))return COURSES[0];return s.toUpperCase()};
function setRolePkg(role,pkg){if(role){S.role=role;S.sugg=rank(role);if(!S.iconManual)S.icon=S.sugg[0]}if(pkg){S.pkg=pkg;S.pkgOn=true}syncUI()}
function manualAdd(){const n=$('mn').value.trim();if(!n){$('mst').textContent='Naam likhiye';return}
 const add=ph=>{const o={name:n,course:$('mc').value,photo:ph||'',upg:false};if(S.st.length===1&&!S.st[0].name&&!S.st[0].photo)S.st[0]=o;else S.st.push(o);setRolePkg($('mr').value.trim(),pkgNum($('mp').value));render();autoBgUp(S.st.length-1);$('mst').textContent='Added: '+n;$('mn').value='';$('mf').value=''};
 const f=$('mf').files[0];f?fileURL(f,add):add('')}
function shMode(){const k=document.querySelector('input[name=sm]:checked').value==='k';$('sl').style.display=k?'none':'block';$('sk').style.display=k?'block':'none'}
function csvParse(s){const r=[];let row=[],c='',q=false;for(let i=0;i<s.length;i++){const ch=s[i];if(q){if(ch=='"'){if(s[i+1]=='"'){c+='"';i++}else q=false}else c+=ch}else if(ch=='"')q=true;else if(ch==','){row.push(c);c=''}else if(ch=='\n'||ch=='\r'){if(ch=='\r'&&s[i+1]=='\n')i++;row.push(c);r.push(row);row=[];c=''}else c+=ch}if(c||row.length){row.push(c);r.push(row)}return r.filter(x=>x.some(v=>v.trim()))}
function sheetURL(u){u=u.trim();if(/\/d\/e\//.test(u))return u.replace(/pubhtml.*/,'pub?output=csv').replace(/\/pub\?(?!.*output=csv)/,'/pub?output=csv&');if(/output=csv/.test(u))return u;const m=u.match(/spreadsheets\/d\/([\w-]+)/);if(!m)return u;const g=(u.match(/gid=(\d+)/)||[])[1];return`https://docs.google.com/spreadsheets/d/${m[1]}/gviz/tq?tqx=out:csv${g?'&gid='+g:''}`}
let SH={head:[],rows:[],map:{}};
async function fetchSheet(){const st=$('shst');st.style.color='#555';st.textContent='Loading...';
 try{let rows;if(document.querySelector('input[name=sm]:checked').value==='k'){const r=await fetch(`https://sheets.googleapis.com/v4/spreadsheets/${encodeURIComponent($('shid').value.trim())}/values/${encodeURIComponent($('shr').value.trim()||'Sheet1')}?key=${encodeURIComponent($('shk').value.trim())}`),j=await r.json();if(j.error)throw new Error(j.error.message);rows=j.values||[]}
  else{const r=await fetch(sheetURL($('shu').value));if(!r.ok)throw new Error('HTTP '+r.status);rows=csvParse(await r.text())}
  if(rows.length<2)throw new Error('Sheet me data nahi mila');gotRows(rows);st.style.color='#2e7d32';st.textContent=(rows.length-1)+' rows mili'}
 catch(e){st.style.color='#c62828';st.textContent='Fail: '+e.message+' (sheet "Anyone with the link - Viewer" ya Publish to web hona chahiye)'}}
const COLS=[['name','Full Name',/full\s*name|^name|candidate|student/],['role','Designation',/designation|role|position|profile|job/],['pkg','Package',/package|ctc|lpa|salary/],['photo','Photo Drive Link',/photo|image|picture|pic|drive/],['course','Course (optional)',/course|program|branch|degree/]];
function gotRows(rows){SH.head=rows[0].map(h=>String(h).trim());SH.rows=rows.slice(1);SH.map={};const used=new Set();
 COLS.forEach(([k,,re])=>{const i=SH.head.findIndex((h,j)=>!used.has(j)&&re.test(h.toLowerCase()));if(i>=0){SH.map[k]=i;used.add(i)}});mapUI()}
function groups(){const m=SH.map,g={};SH.rows.forEach((r,i)=>{if(m.name===undefined||!(r[m.name]||'').trim())return;const ro=m.role!==undefined?(r[m.role]||'').trim():'',pk=m.pkg!==undefined?pkgNum(r[m.pkg]):'',key=ro+'|'+pk;(g[key]=g[key]||{ro,pk,rows:[]}).rows.push(r)});return g}
function mapUI(){const opt=k=>`<option value="">- none -</option>`+SH.head.map((h,i)=>`<option value="${i}" ${SH.map[k]===i?'selected':''}>${esc(h)}</option>`).join('');
 $('shmap').innerHTML=`<h3 style="margin:10px 0 2px">Column mapping</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:4px 10px">${COLS.map(([k,l])=>`<div><label>${l}</label><select onchange="SH.map['${k}']=this.value===''?undefined:+this.value;grpUI()">${opt(k)}</select></div>`).join('')}</div><div id="shg"></div>`;grpUI()}
function grpUI(){const g=groups(),ks=Object.keys(g);window.GR_=g;$('shg').innerHTML=ks.length?`<label>Kaun se candidates (designation + package ke hisaab se group)</label><select id="shsel">${ks.map(k=>`<option value="${esc(k)}">${esc(g[k].ro||'(no designation)')} - ${g[k].pk?g[k].pk+' LPA':'no package'} (${g[k].rows.length})</option>`).join('')}<option value="*">All rows (${Object.values(g).reduce((a,x)=>a+x.rows.length,0)})</option></select><label><input type="checkbox" id="shrep" checked> Maujooda students replace karein</label><div style="margin-top:8px"><button class="g" onclick="loadSheet()">Load on poster</button> <span id="shl" style="font-size:12px"></span></div>`:'<p style="color:#c62828;font-size:12px">Full Name column map kijiye.</p>'}
/* Google Drive link -> direct image (lh3), fetch as data URL so export me CORS error na aaye */
const driveId=u=>{u=(u||'').trim();if(!/drive\.google|googleusercontent|docs\.google/.test(u))return null;const m=u.match(/\/d\/([\w-]{10,})/)||u.match(/[?&]id=([\w-]{10,})/);return m&&m[1]};
const photoCands=u=>{const id=driveId(u);return id?[`https://lh3.googleusercontent.com/d/${id}`,`https://drive.google.com/thumbnail?id=${id}&sz=w1000`,`https://drive.google.com/uc?export=view&id=${id}`]:[(u||'').trim()]};
async function getPhoto(u){if(!u)return'';const c=photoCands(u);for(const x of c){try{const r=await fetch(x,{mode:'cors'});if(!r.ok)continue;const b=await r.blob();if(!/image/.test(b.type))continue;return await new Promise(ok=>{const f=new FileReader();f.onload=()=>ok(f.result);f.readAsDataURL(b)})}catch(e){}}return c[0]}
async function loadSheet(){const v=$('shsel').value,g=window.GR_,m=SH.map,rows=v==='*'?Object.values(g).flatMap(x=>x.rows):g[v].rows,first=v==='*'?Object.values(g)[0]:g[v];
 const list=rows.map(r=>({name:(r[m.name]||'').trim(),course:normCourse(m.course!==undefined?r[m.course]:''),photo:'',upg:false,_u:m.photo!==undefined?(r[m.photo]||'').trim():''}));
 const old=$('shrep').checked?[]:S.st.filter(s=>s.name||s.photo);S.st=[...old,...list];setRolePkg(first.ro,first.pk);render();
 let n=0;const sl=$('shl');sl.textContent='Photos: 0/'+list.length;
 for(const s of list){s.photo=await getPhoto(s._u);delete s._u;n++;sl.textContent=`Photos: ${n}/${list.length}`;render();await autoBgUp(S.st.indexOf(s))}
 sl.textContent=`${list.length} candidates load ho gaye`+(list.some(s=>/^https?:/.test(s.photo))?' (kuch photos CORS ki wajah se direct URL se dikh rahi hain - export me blank aa sakti hain, photo ko "Anyone with link" share karein)':'');stuUI()}

