const EYE1='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>';
const EYE0='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17.9 17.9A10.9 10.9 0 0 1 12 19C5.5 19 2 12 2 12a18.5 18.5 0 0 1 5-5.9M9.9 4.2A9.1 9.1 0 0 1 12 4c6.5 0 10 8 10 8a18.5 18.5 0 0 1-2.2 3.2M1 1l22 22"/></svg>';
const LN={ttl:'Institute title',hdL:'DAVV logo',hdR:'IPS logo',dv:'Header divider',cg:'Congratulations',ach:'Achievement line',bn:'Batch banner',rb:'Selected-at ribbon',lg:'Company logo',as:'AS divider',rl:'Role / designation',pk:'Package',tg:'Tagline',wb:'Wishing bar',ft:'Footer',dotL:'Dots (left)',dotR:'Dots (right)',sp1:'Sparkle (left)',sp2:'Sparkle (right)'};
const nm=k=>LN[k]||(/^c\d+$/.test(k)?'Student '+(+k.slice(1)+1):(/^x\d+$/.test(k)?'Component: '+((DECO[(S.deco.find(d=>'x'+d.id===k)||{}).t]||[])[1]||''):k));
function insp(){const b=$('insp');if(!b)return;const a=document.activeElement;if(a&&b.contains(a)&&a.tagName!=='BUTTON')return;
 const k=S.sk,e=k&&el(k);let h='';
 if(!k||!e)h='<p class="mut">Poster par koi element click karke select karein.</p>';
 else{const x=S.xf[k]||{sx:1,sy:1},w=Math.round(e.offsetWidth*x.sx),hh=Math.round(e.offsetHeight*x.sy),op=Math.round((S.op[k]!==undefined?S.op[k]:1)*100);
  h=`<div class="ih"><b>${esc(nm(k))}</b><button class="s" title="Show / hide" onclick="togHid('${k}')">${S.hid[k]?EYE0:EYE1}</button></div>
  <div class="ir"><label>W</label><input type="number" min="5" value="${w}" onchange="setSize('w',+this.value)"><label>H</label><input type="number" min="5" value="${hh}" onchange="setSize('h',+this.value)"></div>
  <label>Opacity <span id="opv">${op}%</span></label><input type="range" min="0" max="100" value="${op}" oninput="setOp(+this.value)" style="width:100%">
  <label>Flip</label><div><button class="s" onclick="flipA('x')">&#8644; Flip horizontal</button><button class="s" onclick="flipA('y')">&#8645; Flip vertical</button></div><label>Layer order</label><div><button class="s" onclick="layerTo(1)">⤒ Bring to front</button><button class="s" onclick="layer(1);insp()">▲ Forward</button><button class="s" onclick="layer(-1);insp()">▼ Backward</button><button class="s" onclick="layerTo(0)">⤓ Send to back</button></div>`}
 const ks=[...new Set([...P.querySelectorAll('[data-k]')].map(e=>e.dataset.k))];
 h+=`<details ${S.lyOpen?'open':''} ontoggle="S.lyOpen=this.open" style="margin-top:8px"><summary style="font-size:12px;cursor:pointer"><b>Layers (${ks.length})</b> - eye = show/hide</summary>${ks.map(q=>`<div class="ly ${q===S.sk?'on':''}" onclick="selLy('${q}')"><span>${esc(nm(q))}</span><button class="s" onclick="event.stopPropagation();togHid('${q}')">${S.hid[q]?EYE0:EYE1}</button></div>`).join('')}</details>`;
 if(h!==b._h){b.innerHTML=h;b._h=h}}
function selLy(k){selK(k,el(k)||document.body);updateOv()}
